export interface QueuedAction {
  id: string;
  type: string;
  payload: unknown;
  createdAt: number;
}
export interface QueueEntry extends QueuedAction {
  status: 'pending' | 'syncing' | 'synced' | 'failed';
}
export interface QueueSnapshot { actions: QueueEntry[]; isOnline: boolean }

// shortcut: memory-only queue; add durable storage before promising survival across app restarts.
export class ActionQueue {
  private items: QueueEntry[] = [];
  private nextId = 0;
  private online = false;
  private syncing = false;
  private listeners = new Set<() => void>();

  // The caller supplies real transport and server-scoped idempotency; local IDs are queue-local only.
  constructor(private send: (action: QueuedAction) => Promise<void>) {}

  snapshot(): QueueSnapshot {
    return { actions: this.items.map(item => ({ ...item })), isOnline: this.online };
  }
  pending(): QueuedAction[] {
    return this.items.filter(item => item.status !== 'synced').map(item => ({ ...item }));
  }
  subscribe(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => { this.listeners.delete(listener); };
  }
  private notify(): void { this.listeners.forEach(listener => listener()); }
  private status(id: string, status: QueueEntry['status']): void {
    this.items = this.items.map(item => item.id === id ? { ...item, status } : item);
    this.notify();
  }
  enqueue(action: Omit<QueuedAction, 'id' | 'createdAt'>): QueuedAction {
    const item: QueueEntry = { ...action, id: `q-${this.nextId++}`, createdAt: Date.now(), status: 'pending' };
    this.items = [...this.items, item];
    this.notify();
    void this.flush();
    return { ...item };
  }
  setOnline(online: boolean): void {
    const reconnected = online && !this.online;
    this.online = online;
    if (reconnected) this.items = this.items.map(item => item.status === 'failed' ? { ...item, status: 'pending' } : item);
    this.notify();
    if (online) void this.flush();
  }
  retry(id: string): void {
    if (!this.items.some(item => item.id === id && item.status === 'failed')) return;
    this.status(id, 'pending');
    void this.flush();
  }
  private async flush(): Promise<void> {
    if (this.syncing || !this.online) return;
    this.syncing = true;
    try {
      while (this.online) {
        const item = this.items.find(action => action.status === 'pending');
        if (!item) break;
        this.status(item.id, 'syncing');
        try {
          await this.send({ id: item.id, type: item.type, payload: item.payload, createdAt: item.createdAt });
          this.status(item.id, 'synced');
        } catch {
          this.status(item.id, 'failed');
          // Do not spin on a failing request; manual retry or reconnection retries this item.
        }
      }
    } finally {
      this.syncing = false;
    }
  }
}

import { useEffect, useState } from 'react';
import NetInfo from '@react-native-community/netinfo';
import type { ActionQueue, QueueSnapshot } from '../store/queue';

export function useOfflineQueue(queue: ActionQueue): QueueSnapshot {
  const [state, setState] = useState(() => queue.snapshot());
  useEffect(() => {
    const unsubscribeQueue = queue.subscribe(() => setState(queue.snapshot()));
    setState(queue.snapshot());
    const unsubscribeNetwork = NetInfo.addEventListener(connection => {
      queue.setOnline(connection.isConnected === true && connection.isInternetReachable !== false);
    });
    return () => { unsubscribeNetwork(); unsubscribeQueue(); };
  }, [queue]);
  return state;
}

import { FlatList, Pressable, SafeAreaView, StyleSheet, Text, View } from 'react-native';
import { useOfflineQueue } from '../hooks/useOfflineQueue';
import type { ActionQueue } from '../store/queue';

export function QueueScreen({ queue }: { queue: ActionQueue }): JSX.Element {
  const { actions, isOnline } = useOfflineQueue(queue);
  // Failed increments are removed from the optimistic total without erasing successful actions.
  const count = actions.filter(item => item.type === 'increment' && item.status !== 'failed').length;
  return (
    <SafeAreaView style={styles.safe}>
      <Text>{isOnline ? 'Online' : 'Offline — actions queued'}</Text>
      <Text>Demo counter: {count}</Text>
      <Text>Queue is kept in memory only; closing the app loses pending actions.</Text>
      <Pressable style={styles.button} accessibilityRole="button" accessibilityLabel="Increment counter"
        onPress={() => queue.enqueue({ type: 'increment', payload: null })}>
        <Text>Increment counter</Text>
      </Pressable>
      <FlatList
        data={actions}
        keyExtractor={item => item.id}
        renderItem={({ item }) => (
          <View style={styles.row}>
            <Text accessibilityLiveRegion="polite">{item.type} · {item.status}</Text>
            {item.status === 'failed' ? (
              <Pressable style={styles.button} accessibilityRole="button" accessibilityLabel={`Retry action ${item.id}`}
                onPress={() => queue.retry(item.id)}>
                <Text>Retry</Text>
              </Pressable>
            ) : null}
          </View>
        )}
        ListEmptyComponent={<Text>No queued actions.</Text>}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, padding: 16 },
  row: { paddingVertical: 8 },
  button: { padding: 12, borderWidth: 1, borderRadius: 8 },
});
